#include <stdio.h>

/* teste do desafio maioridade-caixa — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Fase VALOR: nao ha captura de tela — o teste declara o PROTOTIPO da caixa
   do aluno e compara o VALOR DEVOLVIDO com checa_int.
   _Bool e o nome oficial do tipo que o stdbool.h apelida de bool: o cartaz
   abaixo casa exatamente com a caixa que voce escreve com bool. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
_Bool maioridadeCaixa(int idade);

SM_TEST(com_21_a_caixa_devolve_um) {
    checa_int("com 21 anos a caixa devolve 1", maioridadeCaixa(21), 1,
              "21 alcanca 18: a comparacao vale 1 e o return entrega esse 1");
}

SM_TEST(com_15_a_caixa_devolve_zero) {
    checa_int("com 15 anos a caixa devolve 0", maioridadeCaixa(15), 0,
              "15 nao alcanca 18: a comparacao vale 0, e e o 0 que volta");
}

SM_TEST(com_18_a_caixa_ainda_devolve_um) {
    checa_int("com 18 anos a caixa ainda devolve 1", maioridadeCaixa(18), 1,
              "o sinal >= aceita o igual: com 18 a resposta continua 1");
}
